//! The read side: sessions and turns, as a client browses them.
//!
//! One structure, fed two ways. The live server folds events into it as they
//! happen; `luu export` folds a recorded file into it. That is deliberate — a
//! static mirror of this API that was generated by different code than the
//! server would drift, and the day it drifts it lies about the thing it exists
//! to stand in for.

use serde::{Deserialize, Serialize};

use crate::backend::Usage;
use crate::context::{Counter, Evicted};
use crate::protocol::{ServerMessage, TurnId};
use crate::record::RecordLine;
use crate::sandbox::Verdict;
use crate::task::{Plan, PlanSource, TaskId, TaskState};
use crate::trace::{Bucket, TraceMessage};
use crate::turn::EndReason;

/// How the context was spent on one turn, as we measured it before the call.
/// `usage` on the same turn is the backend's own count afterwards; the two
/// differ by the chat template we never see, and that difference is a reading,
/// not an error.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Budget {
    /// `None` when the model's window is unknown.
    pub limit: Option<u32>,
    pub counter: Counter,
    pub buckets: Vec<Bucket>,
}

/// How much of this turn's prompt the previous one already contained. `None`
/// on the first turn of a session, where there is nothing to compare against.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct PrefixReuse {
    pub shared_bytes: usize,
    pub shared_tokens: u32,
    pub prompt_tokens: u32,
}

/// One model call a turn made *after* its first.
///
/// A turn that uses a tool is several calls, and the backend's
/// `usage.prompt_tokens` is summed over all of them. Without these the panel
/// compares our count of one call against the backend's count of three, and
/// presents the difference as chat-template overhead. See
/// `RECORD/2026-08-27.the-m4-pro-run.completed.md`, which is where a 1 962-token gap
/// turned out to be this.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExtraCall {
    /// Counts from 1 within the turn, so these start at 2.
    pub step: u32,
    pub prompt_tokens: u32,
    pub shared_bytes: usize,
    pub shared_tokens: u32,
}

/// One tool call as a client browses it — the "tool call timeline" panel the
/// design asks for, which is arguments, verdict, duration and result size.
///
/// The result half is optional because a call that was made and has not come
/// back yet is a real state, and a panel that waits for both would show nothing
/// while a command runs.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolCallView {
    pub step: u32,
    pub name: String,
    pub arguments: serde_json::Value,
    /// Allowed or denied, and *which rule* matched — plus who enforced it.
    pub verdict: Option<Verdict>,
    pub error: Option<String>,
    pub output: String,
    pub truncated: bool,
    pub duration_ms: Option<u64>,
}

/// One task as a client browses it. The transcript groups by this, which is
/// the point: the view collapses exactly what the context collapses.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TaskView {
    pub id: TaskId,
    pub objective: String,
    /// The plan the task is held to: as approved once it has been, as proposed
    /// until then.
    pub plan: Plan,
    /// The plan as it was *proposed*, kept beside the one above because the
    /// difference between them is the cost of the gate — how much a person had
    /// to add before a small model's plan could run. Overwriting it at approval
    /// left that readable only by diffing two lines of a recording by hand.
    #[serde(default)]
    pub proposed: Option<Plan>,
    /// Whether a planning call produced the proposal, or answered in prose.
    /// `None` in a recording made before the distinction existed.
    #[serde(default)]
    pub source: Option<PlanSource>,
    pub state: TaskState,
    /// What its turns are sent as once it is closed. The summary text only —
    /// its token count belongs to whoever counted it, and a reader who needs
    /// that has the budget on the turn beside it.
    pub summary: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TurnView {
    pub turn: TurnId,
    /// The task it was asked inside, when there was one.
    #[serde(default)]
    pub task: Option<TaskId>,
    /// What the user asked.
    pub prompt: String,
    /// What the model produced, assembled. Partial on a cancel or a failure.
    pub text: String,
    pub reason: Option<EndReason>,
    pub usage: Option<Usage>,
    pub error: Option<String>,
    /// The exact string handed to the model — the trace channel's, not a
    /// reconstruction. `None` when the turn was recorded without `--trace`.
    pub prompt_sent: Option<String>,
    pub budget: Option<Budget>,
    /// What the prompt cache could reuse of the previous turn's prompt.
    pub prefix: Option<PrefixReuse>,
    /// The round trips after the first, when the turn used a tool. `budget` and
    /// `prefix` describe the first call only, so a client that adds these up is
    /// the only one whose total matches `usage`.
    #[serde(default)]
    pub extra_calls: Vec<ExtraCall>,
    /// What the agent did during the turn, in order.
    #[serde(default)]
    pub tools: Vec<ToolCallView>,
    /// What this turn's selection dropped from the window, when it dropped
    /// anything. Beside the budget rather than inside it: the buckets say what
    /// the prompt is worth, this says what stopped being in it.
    #[serde(default)]
    pub dropped: Option<Evicted>,
    /// The turn whose selection dropped *this* one. The transcript keeps an
    /// evicted turn and marks it — removing it would make the view agree with
    /// the prompt and lose the difference between them, which is the one thing
    /// a debug client is for.
    #[serde(default)]
    pub evicted_by: Option<TurnId>,
    pub started_at_ms: u64,
    pub ended_at_ms: Option<u64>,
}

impl TurnView {
    fn new(turn: TurnId, task: Option<TaskId>, prompt: String, started_at_ms: u64) -> Self {
        Self {
            turn,
            task,
            prompt,
            text: String::new(),
            reason: None,
            usage: None,
            error: None,
            prompt_sent: None,
            budget: None,
            prefix: None,
            extra_calls: Vec::new(),
            tools: Vec::new(),
            dropped: None,
            evicted_by: None,
            started_at_ms,
            ended_at_ms: None,
        }
    }

    pub fn is_running(&self) -> bool {
        self.ended_at_ms.is_none()
    }
}

/// What `GET /api/sessions` lists: enough to choose one, without its turns.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SessionSummary {
    pub id: String,
    pub title: String,
    pub backend: String,
    pub model: String,
    pub started_at: u64,
    pub turns: usize,
    /// Where the replayable recording lives, when there is one. The UI streams
    /// this rather than the summaries, because a summary cannot show timing.
    pub record: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SessionView {
    pub id: String,
    pub title: String,
    pub backend: String,
    pub model: String,
    pub started_at: u64,
    pub turns: Vec<TurnView>,
    /// In the order they were proposed. Empty for a session that ran without
    /// tasks, which is every session recorded before they existed.
    #[serde(default)]
    pub tasks: Vec<TaskView>,
    pub record: Option<String>,
}

impl SessionView {
    pub fn new(
        id: impl Into<String>,
        backend: impl Into<String>,
        model: impl Into<String>,
    ) -> Self {
        let id = id.into();
        Self {
            title: id.clone(),
            id,
            backend: backend.into(),
            model: model.into(),
            started_at: 0,
            turns: Vec::new(),
            tasks: Vec::new(),
            record: None,
        }
    }

    pub fn summary(&self) -> SessionSummary {
        SessionSummary {
            id: self.id.clone(),
            title: self.title.clone(),
            backend: self.backend.clone(),
            model: self.model.clone(),
            started_at: self.started_at,
            turns: self.turns.len(),
            record: self.record.clone(),
        }
    }

    pub fn turn(&self, turn: TurnId) -> Option<&TurnView> {
        self.turns.iter().find(|t| t.turn == turn)
    }

    fn turn_mut(&mut self, turn: TurnId) -> Option<&mut TurnView> {
        self.turns.iter_mut().find(|t| t.turn == turn)
    }

    pub fn task(&self, task: TaskId) -> Option<&TaskView> {
        self.tasks.iter().find(|t| t.id == task)
    }

    fn task_mut(&mut self, task: TaskId) -> Option<&mut TaskView> {
        self.tasks.iter_mut().find(|t| t.id == task)
    }

    /// Folds one protocol message in. `at_ms` is milliseconds since the session
    /// started, the same clock the record file uses.
    pub fn apply_protocol(&mut self, at_ms: u64, message: &ServerMessage) {
        match message {
            ServerMessage::Hello { backend, model, .. } => {
                self.backend = backend.clone();
                self.model = model.clone();
            }
            ServerMessage::TurnStarted { turn, prompt, task } => {
                if self.turn(*turn).is_none() {
                    self.turns
                        .push(TurnView::new(*turn, *task, prompt.clone(), at_ms));
                }
            }
            ServerMessage::TaskProposed {
                task,
                objective,
                plan,
                source,
            } => {
                if self.task(*task).is_none() {
                    self.tasks.push(TaskView {
                        id: *task,
                        objective: objective.clone(),
                        plan: plan.clone(),
                        proposed: Some(plan.clone()),
                        source: *source,
                        state: TaskState::Proposed,
                        summary: None,
                    });
                }
            }
            ServerMessage::Evicted {
                turn,
                turns,
                tokens,
                counter,
                policy,
            } => {
                if let Some(view) = self.turn_mut(*turn) {
                    view.dropped = Some(Evicted {
                        turns: turns.clone(),
                        tokens: *tokens,
                        counter: counter.clone(),
                        policy: *policy,
                    });
                }
                // Both halves, because a reader asks it both ways: what did
                // this turn cost the history, and is that turn still in the
                // prompt.
                for dropped in turns {
                    if let Some(view) = self.turn_mut(*dropped) {
                        view.evicted_by = Some(*turn);
                    }
                }
            }
            // Transient feedback to whoever asked, not session state: a
            // refusal is a thing the server declined to do, and there is
            // nothing about the session afterwards that is different for it.
            // It stays out of the view until something wants to count them.
            ServerMessage::Refused { .. } => {}
            ServerMessage::TaskApproved { task, plan } => {
                if let Some(view) = self.task_mut(*task) {
                    view.state = TaskState::Approved;
                    // The plan as approved, which is what the task's sandbox is
                    // built from. An older recording carries none, and then what
                    // was proposed is the best answer there is.
                    if plan != &Plan::default() {
                        view.plan = plan.clone();
                    }
                }
            }
            ServerMessage::TaskClosed { task, summary } => {
                if let Some(view) = self.task_mut(*task) {
                    view.state = TaskState::Closed;
                    view.summary = Some(summary.clone());
                }
            }
            ServerMessage::TaskRejected { task } => {
                if let Some(view) = self.task_mut(*task) {
                    view.state = TaskState::Rejected;
                }
            }
            ServerMessage::TaskReopened { task } => {
                if let Some(view) = self.task_mut(*task) {
                    view.state = TaskState::Approved;
                    // Dropped rather than kept beside the reopened task: it is
                    // an account of work that is being written again.
                    view.summary = None;
                }
            }
            ServerMessage::Token { turn, text } => {
                if let Some(view) = self.turn_mut(*turn) {
                    view.text.push_str(text);
                }
            }
            ServerMessage::Ended {
                turn,
                reason,
                usage,
            } => {
                if let Some(view) = self.turn_mut(*turn) {
                    view.reason = Some(*reason);
                    view.usage = *usage;
                    view.ended_at_ms = Some(at_ms);
                }
            }
            ServerMessage::Failed { turn, message } => {
                if let Some(view) = self.turn_mut(*turn) {
                    view.error = Some(message.clone());
                    view.ended_at_ms = Some(at_ms);
                }
            }
            ServerMessage::ToolCall {
                turn,
                step,
                name,
                arguments,
            } => {
                if let Some(view) = self.turn_mut(*turn)
                    && !view.tools.iter().any(|call| call.step == *step)
                {
                    view.tools.push(ToolCallView {
                        step: *step,
                        name: name.clone(),
                        arguments: arguments.clone(),
                        verdict: None,
                        error: None,
                        output: String::new(),
                        truncated: false,
                        duration_ms: None,
                    });
                }
            }
            ServerMessage::ToolResult {
                turn,
                step,
                verdict,
                error,
                output,
                truncated,
                duration_ms,
                ..
            } => {
                if let Some(view) = self.turn_mut(*turn)
                    && let Some(call) = view.tools.iter_mut().find(|call| call.step == *step)
                {
                    call.verdict = Some(verdict.clone());
                    call.error = error.clone();
                    call.output = output.clone();
                    call.truncated = *truncated;
                    call.duration_ms = Some(*duration_ms);
                }
            }
        }
    }

    pub fn apply_trace(&mut self, _at_ms: u64, message: &TraceMessage) {
        match message {
            TraceMessage::Prompt { turn, text } => {
                if let Some(view) = self.turn_mut(*turn) {
                    view.prompt_sent = Some(text.clone());
                }
            }
            TraceMessage::Budget {
                turn,
                limit,
                counter,
                buckets,
            } => {
                if let Some(view) = self.turn_mut(*turn) {
                    view.budget = Some(Budget {
                        limit: *limit,
                        counter: counter.clone(),
                        buckets: buckets.clone(),
                    });
                }
            }
            TraceMessage::PrefixReuse {
                turn,
                shared_bytes,
                shared_tokens,
                prompt_tokens,
            } => {
                if let Some(view) = self.turn_mut(*turn) {
                    view.prefix = Some(PrefixReuse {
                        shared_bytes: *shared_bytes,
                        shared_tokens: *shared_tokens,
                        prompt_tokens: *prompt_tokens,
                    });
                }
            }
            TraceMessage::StepCall {
                turn,
                step,
                prompt_tokens,
                shared_bytes,
                shared_tokens,
                ..
            } => {
                if let Some(view) = self.turn_mut(*turn) {
                    view.extra_calls.push(ExtraCall {
                        step: *step,
                        prompt_tokens: *prompt_tokens,
                        shared_bytes: *shared_bytes,
                        shared_tokens: *shared_tokens,
                    });
                }
            }
        }
    }

    /// Rebuilds a session from a recording. The header names the backend and
    /// model, so a replayed session reports what actually produced it.
    pub fn from_record(id: impl Into<String>, lines: &[RecordLine]) -> Self {
        let mut view = Self::new(id, "", "");
        for line in lines {
            match line {
                RecordLine::Header {
                    backend,
                    model,
                    started_at,
                    ..
                } => {
                    view.backend = backend.clone();
                    view.model = model.clone();
                    view.started_at = *started_at;
                }
                RecordLine::Protocol { at_ms, message } => view.apply_protocol(*at_ms, message),
                RecordLine::Trace { at_ms, message } => view.apply_trace(*at_ms, message),
            }
        }
        view
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::record::{self, RecordLine};

    fn lines() -> Vec<RecordLine> {
        vec![
            RecordLine::Header {
                format: record::FORMAT,
                protocol: crate::protocol::VERSION,
                backend: "mock".into(),
                model: "mock".into(),
                context_limit: Some(8192),
                counter: Some(Counter::Model { id: "mock".into() }),
                eviction: Some(crate::context::Eviction::Turn),
                started_at: 1_700_000_000_000,
            },
            RecordLine::Protocol {
                at_ms: 0,
                message: ServerMessage::TurnStarted {
                    turn: 1,
                    prompt: "hola".into(),
                    task: None,
                },
            },
            RecordLine::Trace {
                at_ms: 0,
                message: TraceMessage::Prompt {
                    turn: 1,
                    text: "<|System|>\nx".into(),
                },
            },
            RecordLine::Protocol {
                at_ms: 10,
                message: ServerMessage::Token {
                    turn: 1,
                    text: "bue".into(),
                },
            },
            RecordLine::Protocol {
                at_ms: 20,
                message: ServerMessage::Token {
                    turn: 1,
                    text: "nas".into(),
                },
            },
            RecordLine::Protocol {
                at_ms: 30,
                message: ServerMessage::Ended {
                    turn: 1,
                    reason: EndReason::Stop,
                    usage: Some(Usage {
                        prompt_tokens: 5,
                        completion_tokens: 2,
                    }),
                },
            },
        ]
    }

    /// A second turn, which is the first one that can carry a prefix
    /// measurement: there is a previous prompt to measure against.
    fn second_turn() -> Vec<RecordLine> {
        vec![
            RecordLine::Protocol {
                at_ms: 40,
                message: ServerMessage::TurnStarted {
                    turn: 2,
                    prompt: "y otra".into(),
                    task: None,
                },
            },
            RecordLine::Trace {
                at_ms: 40,
                message: TraceMessage::Prompt {
                    turn: 2,
                    text: "<|System|>\nx2".into(),
                },
            },
            RecordLine::Trace {
                at_ms: 40,
                message: TraceMessage::PrefixReuse {
                    turn: 2,
                    shared_bytes: 12,
                    shared_tokens: 3,
                    prompt_tokens: 4,
                },
            },
            RecordLine::Protocol {
                at_ms: 60,
                message: ServerMessage::Ended {
                    turn: 2,
                    reason: EndReason::Stop,
                    usage: None,
                },
            },
        ]
    }

    #[test]
    fn a_recording_rebuilds_the_session_it_recorded() {
        let view = SessionView::from_record("completed", &lines());
        assert_eq!(view.backend, "mock");
        assert_eq!(view.turns.len(), 1);

        let turn = view.turn(1).unwrap();
        assert_eq!(turn.text, "buenas", "tokens are assembled in order");
        assert_eq!(turn.prompt, "hola");
        assert_eq!(turn.reason, Some(EndReason::Stop));
        assert_eq!(turn.usage.unwrap().prompt_tokens, 5);
        assert_eq!(turn.ended_at_ms, Some(30));
        assert!(
            turn.prompt_sent.is_some(),
            "the trace channel's prompt is kept"
        );
        assert!(!turn.is_running());
    }

    #[test]
    fn the_first_turn_has_no_prefix_to_measure_against() {
        let view = SessionView::from_record("completed", &lines());
        assert!(
            view.turn(1).unwrap().prefix.is_none(),
            "0% on turn one would read as a cold cache rather than as no cache",
        );

        let both = [lines(), second_turn()].concat();
        let reuse = SessionView::from_record("s", &both)
            .turn(2)
            .unwrap()
            .prefix
            .unwrap();
        assert_eq!(reuse.shared_tokens, 3);
        assert_eq!(reuse.prompt_tokens, 4);
    }

    #[test]
    fn folding_live_events_gives_the_same_view_as_folding_the_record() {
        // Two turns, so every trace message the fold understands is covered:
        // the prefix measurement only exists from the second turn onwards.
        let all = [lines(), second_turn()].concat();
        let recorded = SessionView::from_record("s", &all);

        // The same messages, applied one at a time the way the server does.
        let mut live = SessionView::new("s", "mock", "mock");
        live.started_at = 1_700_000_000_000;
        for line in all {
            match line {
                RecordLine::Protocol { at_ms, message } => live.apply_protocol(at_ms, &message),
                RecordLine::Trace { at_ms, message } => live.apply_trace(at_ms, &message),
                RecordLine::Header { .. } => {}
            }
        }

        assert_eq!(
            serde_json::to_value(&recorded).unwrap(),
            serde_json::to_value(&live).unwrap(),
            "a static mirror must equal what the live server would serve",
        );
    }

    #[test]
    fn a_cancelled_turn_keeps_its_partial_text_and_reports_no_usage() {
        let mut view = SessionView::new("s", "mock", "mock");
        view.apply_protocol(
            0,
            &ServerMessage::TurnStarted {
                turn: 1,
                prompt: "x".into(),
                task: None,
            },
        );
        view.apply_protocol(
            5,
            &ServerMessage::Token {
                turn: 1,
                text: "par".into(),
            },
        );
        view.apply_protocol(
            9,
            &ServerMessage::Ended {
                turn: 1,
                reason: EndReason::Cancelled,
                usage: None,
            },
        );

        let turn = view.turn(1).unwrap();
        assert_eq!(turn.text, "par");
        assert_eq!(turn.reason, Some(EndReason::Cancelled));
        assert!(turn.usage.is_none());
        assert!(
            turn.budget.is_none(),
            "nothing to plot, so nothing is invented"
        );
    }

    #[test]
    fn an_eviction_marks_both_the_turn_that_cut_and_the_turns_that_left() {
        let mut view = SessionView::new("s", "mock", "mock");
        for turn in 1..=3 {
            view.apply_protocol(
                0,
                &ServerMessage::TurnStarted {
                    turn,
                    prompt: format!("q{turn}"),
                    task: None,
                },
            );
        }
        view.apply_protocol(
            9,
            &ServerMessage::Evicted {
                turn: 3,
                turns: vec![1],
                tokens: 42,
                counter: Counter::Approximate,
                policy: crate::context::Eviction::Turn,
            },
        );

        let dropped = view
            .turn(3)
            .unwrap()
            .dropped
            .clone()
            .expect("what turn 3 cut");
        assert_eq!(dropped.turns, vec![1]);
        assert_eq!(dropped.tokens, 42);
        assert_eq!(
            view.turn(1).unwrap().evicted_by,
            Some(3),
            "the turn is kept and marked: the transcript's job is the difference \
             between what happened and what the model is still shown",
        );
        assert!(
            view.turn(2).unwrap().evicted_by.is_none(),
            "still in the window",
        );
    }

    #[test]
    fn an_eviction_naming_a_turn_the_view_never_saw_is_ignored() {
        // A client that attached mid-session has turns the eviction names and
        // it does not. Marking nothing beats inventing a turn to mark.
        let mut view = SessionView::new("s", "mock", "mock");
        view.apply_protocol(
            0,
            &ServerMessage::TurnStarted {
                turn: 7,
                prompt: "q".into(),
                task: None,
            },
        );
        view.apply_protocol(
            1,
            &ServerMessage::Evicted {
                turn: 7,
                turns: vec![1, 2],
                tokens: 10,
                counter: Counter::Approximate,
                policy: crate::context::Eviction::Turn,
            },
        );

        assert_eq!(view.turns.len(), 1);
        let dropped = view.turn(7).unwrap().dropped.clone().expect("the cut");
        assert_eq!(dropped.turns, vec![1, 2]);
    }

    #[test]
    fn a_token_for_an_unknown_turn_is_ignored_rather_than_panicking() {
        let mut view = SessionView::new("s", "mock", "mock");
        view.apply_protocol(
            0,
            &ServerMessage::Token {
                turn: 9,
                text: "x".into(),
            },
        );
        assert!(view.turns.is_empty());
    }
}
